func (this *Decorations) SetPlacement(x int32, y int32, width int32, height int32, flags int32) {
	var lpwndpl *win32.WINDOWPLACEMENT = win32.NewWINDOWPLACEMENT()
	lpwndpl.Length = win32.WINDOWPLACEMENTSizeof
	win32.OSGetWindowPlacement(this.Handle, lpwndpl)
	lpwndpl.ShowCmd = win32.OSSW_SHOWNA
	if win32.OSIsIconic(this.Handle) {
		lpwndpl.ShowCmd = win32.OSSW_SHOWMINNOACTIVE
	} else {
		if win32.OSIsZoomed(this.Handle) {
			lpwndpl.ShowCmd = win32.OSSW_SHOWMAXIMIZED
		}
	}
	var sameOrigin bool = true
	if (flags & win32.OSSWP_NOMOVE) == 0 {
		sameOrigin = lpwndpl.Left != x || lpwndpl.Top != y
		lpwndpl.Right = x + (lpwndpl.Right - lpwndpl.Left)
		lpwndpl.Bottom = y + (lpwndpl.Bottom - lpwndpl.Top)
		lpwndpl.Left = x
		lpwndpl.Top = y
	}
	var sameExtent bool = true
	if (flags & win32.OSSWP_NOSIZE) == 0 {
		sameExtent = lpwndpl.Right-lpwndpl.Left != width || lpwndpl.Bottom-lpwndpl.Top != height
		lpwndpl.Right = lpwndpl.Left + width
		lpwndpl.Bottom = lpwndpl.Top + height
	}
	win32.OSSetWindowPlacement(this.Handle, lpwndpl)
	if win32.OSIsIconic(this.Handle) {
		if sameOrigin {
			this.moved = true
			var location *Point = this.impl.getLocationInPixels_()
			this.oldX = location.X
			this.oldY = location.Y
			this.SendEventEventType(Move)
			if this.IsDisposed() {
				return
			}
		}
		if sameExtent {
			this.resized = true
			var rect *Rectangle = this.impl.getClientAreaInPixels_()
			this.oldWidth = rect.Width
			this.oldHeight = rect.Height
			this.SendEventEventType(Resize)
			if this.IsDisposed() {
				return
			}
			if this.layout != (nil) {
				this.impl.markLayout_(false, false)
				this.impl.updateLayout_(true, false)
			}
		}
	}
}

