func (this *Decorations) SetSystemMenu() {
	var hMenu int64 = win32.OSGetSystemMenu(this.Handle, false)
	if hMenu == 0 {
		return
	}
	var oldCount int32 = win32.OSGetMenuItemCount(hMenu)
	if (this.style & RESIZE) == 0 {
		win32.OSDeleteMenu(hMenu, win32.OSSC_SIZE, win32.OSMF_BYCOMMAND)
	}
	if (this.style & MIN) == 0 {
		win32.OSDeleteMenu(hMenu, win32.OSSC_MINIMIZE, win32.OSMF_BYCOMMAND)
	}
	if (this.style & MAX) == 0 {
		win32.OSDeleteMenu(hMenu, win32.OSSC_MAXIMIZE, win32.OSMF_BYCOMMAND)
	}
	if (this.style & (MIN | MAX)) == 0 {
		win32.OSDeleteMenu(hMenu, win32.OSSC_RESTORE, win32.OSMF_BYCOMMAND)
	}
	var newCount int32 = win32.OSGetMenuItemCount(hMenu)
	if (this.style&CLOSE) == 0 || newCount != oldCount {
		win32.OSDeleteMenu(hMenu, win32.OSSC_TASKLIST, win32.OSMF_BYCOMMAND)
		var info *win32.MENUITEMINFO = win32.NewMENUITEMINFO()
		info.CbSize = win32.MENUITEMINFOSizeof
		info.FMask = win32.OSMIIM_ID
		var index int32 = 0
		for index < newCount {
			if win32.OSGetMenuItemInfo(hMenu, index, true, info) {
				if info.WID == win32.OSSC_CLOSE {
					break
				}
			}
			index++
		}
		if index != newCount {
			win32.OSDeleteMenu(hMenu, index-1, win32.OSMF_BYPOSITION)
			if (this.style & CLOSE) == 0 {
				win32.OSDeleteMenu(hMenu, win32.OSSC_CLOSE, win32.OSMF_BYCOMMAND)
			}
		}
	}
}

func (this *Decorations) SetText(string_ string) {
	this.CheckWidget()
	if string_ == jrt.NullString {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	var buffer *win32.TCHAR = win32.NewTCHARStringTerminate(string_, true)
	if (this.state & WidgetFOREIGN_HANDLE) != 0 {
		var hHeap int64 = win32.OSGetProcessHeap()
		var byteCount int32 = buffer.Length() * win32.TCHARSizeof
		var pszText int64 = win32.OSHeapAlloc(hHeap, win32.OSHEAP_ZERO_MEMORY, byteCount)
		win32.OSMoveMemory(pszText, buffer, byteCount)
		win32.OSDefWindowProc(this.Handle, win32.OSWM_SETTEXT, int64(0), pszText)
		if pszText != 0 {
			win32.OSHeapFree(hHeap, 0, pszText)
		}
	} else {
		win32.OSSetWindowText(this.Handle, buffer)
	}
	if (this.state & WidgetHAS_AUTO_DIRECTION) != 0 {
		this.impl.updateTextDirection_(WidgetAUTO_TEXT_DIRECTION)
	}
}

func (this *Decorations) setVisible_(visible bool) {
	this.CheckWidget()
	if !this.GetDrawing() {
		if ((this.state & WidgetHIDDEN) == 0) == visible {
			return
		}
	} else {
		if visible == win32.OSIsWindowVisible(this.Handle) {
			return
		}
	}
	if visible {
		this.SendEventEventType(Show)
		if this.IsDisposed() {
			return
		}
		if !this.GetDrawing() {
			this.state &= ^WidgetHIDDEN
		} else {
			if this.menuBar != (nil) {
				this.display.RemoveBar(this.menuBar)
				win32.OSDrawMenuBar(this.Handle)
			}
			var lpStartUpInfo *win32.STARTUPINFO = DisplayLpStartupInfo
			if lpStartUpInfo != (nil) && (lpStartUpInfo.DwFlags&win32.OSSTARTF_USESHOWWINDOW) != 0 {
				win32.OSShowWindow(this.Handle, int32(lpStartUpInfo.WShowWindow))
			} else {
				win32.OSShowWindow(this.Handle, this.swFlags)
			}
			if this.IsDisposed() {
				return
			}
			this.opened = true
			if !this.moved {
				this.moved = true
				var location *Point = this.impl.getLocationInPixels_()
				this.oldX = location.X
				this.oldY = location.Y
			}
			if !this.resized {
				this.resized = true
				var rect *Rectangle = this.impl.getClientAreaInPixels_()
				this.oldWidth = rect.Width
				this.oldHeight = rect.Height
			}
			win32.OSUpdateWindow(this.Handle)
		}
	} else {
		if win32.OSIsIconic(this.Handle) {
			this.swFlags = win32.OSSW_SHOWMINNOACTIVE
		} else {
			if win32.OSIsZoomed(this.Handle) {
				this.swFlags = win32.OSSW_SHOWMAXIMIZED
			} else {
				this.swFlags = win32.OSSW_SHOWNOACTIVATE
			}
		}
		if !this.GetDrawing() {
			this.state |= WidgetHIDDEN
		} else {
			win32.OSShowWindow(this.Handle, win32.OSSW_HIDE)
		}
		if this.IsDisposed() {
			return
		}
		this.SendEventEventType(Hide)
	}
}

func (this *Decorations) translateAccelerator_(msg *win32.MSG) bool {
	if !this.impl.isEnabled_() || !this.IsActive() {
		return false
	}
	if this.menuBar != (nil) && !this.menuBar.IsEnabled() {
		return false
	}
	if this.TranslateMDIAccelerator(msg) || this.TranslateMenuAccelerator(msg) {
		return true
	}
	var decorations *Decorations = this.parent.impl.menuShell_()
	return decorations.impl.translateAccelerator_(msg)
}

func (this *Decorations) TranslateMenuAccelerator(msg *win32.MSG) bool {
	if this.hAccel == -1 {
		this.CreateAccelerators()
	}
	return this.hAccel != 0 && win32.OSTranslateAccelerator(this.Handle, this.hAccel, msg) != 0
}

func (this *Decorations) TranslateMDIAccelerator(msg *win32.MSG) bool {
	_, ok160 := isDecorationsToShell(this)
	if !(ok160) {
		var shell *Shell = this.impl.getShell_()
		var hwndMDIClient int64 = shell.hwndMDIClient
		if hwndMDIClient != 0 && win32.OSTranslateMDISysAccel(hwndMDIClient, msg) {
			return true
		}
		if msg.Message == win32.OSWM_KEYDOWN {
			if int32(win32.OSGetKeyState(win32.OSVK_CONTROL)) >= 0 {
				return false
			}
			switch int32((msg.WParam)) {
			case win32.OSVK_F4:
				win32.OSPostMessage(this.Handle, win32.OSWM_CLOSE, int64(0), int64(0))
				return true
			case win32.OSVK_F6:
				if this.TraverseDecorations(true) {
					return true
				}
			}
			return false
		}
		if msg.Message == win32.OSWM_SYSKEYDOWN {
			switch int32((msg.WParam)) {
			case win32.OSVK_F4:
				win32.OSPostMessage(shell.Handle, win32.OSWM_CLOSE, int64(0), int64(0))
				return true
			}
			return false
		}
	}
	return false
}

func (this *Decorations) TraverseDecorations(next bool) bool {
	var children []*Control = this.parent._getChildren()
	var length int32 = int32(len(children))
	var index int32 = 0
	for index < length {
		if children[index] == upcastDecorationsToControl(this) {
			break
		}
		index++
	}
	var start int32 = index
	var offset int32
	if next {
		offset = 1
	} else {
		offset = -1
	}
	for {
		cond161 := (index + offset + length) % length
		index = cond161
		if !((cond161) != start) {
			break
		}
		var child *Control = children[index]
		if !child.IsDisposed() && func() bool { _, ok162 := isControlToDecorations(child); return ok162 }() {
			if child.impl.setFocus_() {
				return true
			}
		}
	}
	return false
}

