func (this *Decorations) wM_ACTIVATE_(wParam int64, lParam int64) *win32.LRESULT {
	var result *win32.LRESULT = this.Canvas.wM_ACTIVATE_(wParam, lParam)
	if result != (nil) {
		return result
	}
	if win32.OSGetParent(lParam) == this.Handle {
		var buffer []uint16 = make([]uint16, 128)
		var length int32 = win32.OSGetClassName(lParam, buffer, int32(len(buffer)))
		var className string = string(utf16.Decode(buffer[0 : 0+length]))
		if className == DisplayAWT_WINDOW_CLASS {
			return win32.LRESULTZERO
		}
	}
	var loWord int32 = win32.OSLOWORD(wParam)
	if loWord != 0 {
		if win32.OSHIWORD(wParam) != 0 {
			return result
		}
		var control *Control = this.display.FindControl(lParam)
		if control == (nil) || func() bool { _, ok164 := isControlToShell(control); return ok164 }() {
			_, ok165 := isDecorationsToShell(this)
			if ok165 {
				var event *Event = NewEvent()
				if loWord == int32(win32.OSWA_CLICKACTIVE) {
					event.Detail = MouseDown
				} else {
					event.Detail = None
				}
				this.SendEventEventTypeEvent(Activate, event)
				if this.IsDisposed() {
					return win32.LRESULTZERO
				}
			}
		}
		if this.RestoreFocus() {
			return win32.LRESULTZERO
		}
	} else {
		var display *Display = this.display
		var lockWindow bool = display.IsXMouseActive()
		if lockWindow {
			display.lockActiveWindow = true
		}
		var control *Control = display.FindControl(lParam)
		if control == (nil) || func() bool { _, ok166 := isControlToShell(control); return ok166 }() {
			_, ok167 := isDecorationsToShell(this)
			if ok167 {
				this.SendEventEventType(Deactivate)
				if !this.IsDisposed() {
					var shell *Shell = this.impl.getShell_()
					shell.SetActiveControl(nil)
				}
			}
		}
		if lockWindow {
			display.lockActiveWindow = false
		}
		if this.IsDisposed() {
			return win32.LRESULTZERO
		}
		this.SaveFocus()
	}
	return result
}

